contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _logger) public payable {
        require(_logger != address(this), "logger must not be the test contract");

        bool isApproved = c.approvedToLog(_logger); if (__ESBMC_reverted()) return;
        assert(!isApproved);
    }

    receive() external payable {}
}

